                'study_purpose' => 'Degree study|Language training',
                'description_en' => 'In 2013, Chinese President Xi Jin-ping put forward the strategic initiative of jointly building "Silk Road Economic Belt" and "21st-Century Maritime Silk Road", advocating the reinforcement of interconnection and exchange with adjacent countries of "One Belt& One Road". In April. 2017, Ministry of Education declared that China has established mutual recognition on education and diploma with 24 countries including Poland, Lithuania, Estonia, Latvia, Hungary, Romania, Bulgaria, Czech, Thailand, Vietnam, Philippine, Malaysia, Indonesia, Kazakhstan, Turkmenistan, Kyrgyzstan, Uzbekistan, Armenia, Russia, Ukraine, Belarus, Mongolia, Egypt. To answer the initiative, International Education College of Shanghai University of Traditional Chinese Medicine revised in 2015 "Silk Road" Assistance Fund which aims to provide financial assistance for students from above countries annually.',
